import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api";
import InvoiceTable from "./InvoiceTable";
import InvoiceFilter from "./InvoiceFilter";
import Pagination from "../components/Pagination";
import { Link } from "react-router-dom";

// Main invoices page component
const InvoiceIndex = () => {
    // State for storing invoices, filters, and lists of buyers/sellers
    const [invoices, setInvoices] = useState([]);
    const [filter, setFilter] = useState({ limit: 10, page: 0 }); // Default filter settings
    const [buyerList, setBuyerList] = useState([]);
    const [sellerList, setSellerList] = useState([]);
    const [totalCount, setTotalCount] = useState(0); // Total count of invoices

    // Fetches invoices from the API with the current filters
    const fetchInvoices = async () => {
        const query = new URLSearchParams(filter).toString(); // Convert filter object to query string
        const endpoint = `/api/invoices?${query}`;
        const data = await apiGet(endpoint);
        setInvoices(data);
    };

    // Fetches the total number of invoices matching the filter
    const fetchInvoiceCount = async () => {
        const query = new URLSearchParams(filter).toString();
        const data = await apiGet(`/api/invoices/count?${query}`);
        setTotalCount(data.count);
    };

    // useEffect triggers when the `filter` state changes
    useEffect(() => {
        fetchInvoices(); // Fetch invoice list
        fetchInvoiceCount(); // Fetch count of matching invoices
        apiGet("/api/persons").then(setSellerList); // Load sellers
        apiGet("/api/persons").then(setBuyerList); // Load buyers
    }, [filter]); // Runs whenever `filter` changes

    // Deletes an invoice by ID
    const deleteInvoice = async (id) => {
        try {
            await apiDelete(`/api/invoices/${id}`);
            setInvoices(invoices.filter((item) => item._id !== id)); // Remove deleted invoice from state
        } catch (error) {
            console.error(error.message);
            alert(error.message);
        }
    };

    // Updates filter state when user modifies input fields
    const handleFilterChange = (e) => {
        const { name, value } = e.target;
        setFilter((prev) => {
            const newFilter = { ...prev, [name]: value };
            if (value === "false") {
                delete newFilter[name]; // Remove filter when "false" is selected
            }
            return newFilter;
        });
    };

    return (
        <div>
            <h1>Seznam faktur</h1>
            <InvoiceFilter
                filter={filter} // Passes the current filter state
                handleChange={handleFilterChange}
                confirm="Filtrovat"
                buyerList={buyerList}
                sellerList={sellerList}
            />
            <InvoiceTable deleteInvoice={deleteInvoice} items={invoices} filter={filter} />
            <Pagination filter={filter} setFilter={setFilter} totalCount={totalCount} />
            <Link to={"/invoices/create"} className="btn btn-success invoice-button">
                Nová faktura
            </Link>
        </div>
    );
};

export default InvoiceIndex;
